/**
 * ReGallery Divi 4 Visual Builder bundle.
 *
 * Divi 4 enqueues this file (DiviExtension) in the Visual Builder and then
 * copies the page, including its scripts, into the app frame. The builder's
 * React tree runs in the top window: module components render into the app
 * frame through a portal, settings-modal fields render into the top document.
 *
 *   - top window: registers the module and the `reacg_gallery_picker` field.
 *     The field opens the floating ReacgBuilderModal when the settings modal
 *     shows it, and writes the chosen gallery back with `_onChange`.
 *   - app frame: forwards clicks on the gallery / placeholder to the module
 *     (a double click opens its settings modal, which opens the panel).
 */
(function ($) {
  "use strict";

  var SLUG = "reacg_module";
  var FIELD_SLUG = "reacg_gallery_picker";
  var PANEL_CLOSE_DELAY = 250;
  var ICON_PATH =
    "M16 4h1.96c.57 0 1.04.47 1.04 1.04v12.92c0 .57-.47 1.04-1.04 1.04H5.04C4.47 19 4 18.53 4 17.96V16H2.04C1.47 16 1 15.53 1 14.96V2.04C1 1.47 1.47 1 2.04 1h12.92c.57 0 1.04.47 1.04 1.04V4zM6 6v11h11V6H6zm1 9l2.5-3 1.5 2 2.5-4L15 15H7zM3 3v11h1V5.04C4 4.47 4.47 4 5.04 4H14V3H3z";

  function isAppFrame() {
    try {
      return window.top !== window;
    } catch (e) {
      return true;
    }
  }

  function getTopWindow() {
    try {
      return window.top || window;
    } catch (e) {
      return window;
    }
  }

  function getAppWindow() {
    var topWin = getTopWindow();
    var frame = topWin.document.getElementById("et-fb-app-frame");
    return frame && frame.contentWindow ? frame.contentWindow : null;
  }

  function getData() {
    var topWin = getTopWindow();
    return topWin.reacg_builder_data || window.reacg_builder_data || {};
  }

  function text(key, fallback) {
    var data = getData();
    return data[key] ? String(data[key]) : fallback;
  }

  function getPanel() {
    var topWin = getTopWindow();
    return topWin.ReacgBuilderModal || window.ReacgBuilderModal || null;
  }

  function parseGalleryId(value) {
    var id = parseInt(value, 10);
    return isNaN(id) ? 0 : id;
  }

  function galleryExists(galleryId) {
    if (galleryId === -1) return true;
    var galleries = getData().galleries || {};
    if (Array.isArray(galleries)) {
      return galleries.some(function (g) {
        return parseInt(g.id, 10) === galleryId;
      });
    }
    return Object.prototype.hasOwnProperty.call(galleries, String(galleryId));
  }

  /**
   * Gallery id of a module; a deleted gallery counts as none.
   */
  function effectiveGalleryId(value) {
    var galleryId = parseGalleryId(value);
    return galleryId > 0 && !galleryExists(galleryId) ? 0 : galleryId;
  }

  function getGalleryTitle(galleryId) {
    var galleries = getData().galleries || {};
    var title = "";
    if (Array.isArray(galleries)) {
      galleries.forEach(function (g) {
        if (String(g.id) === String(galleryId)) title = g.title;
      });
    } else if (galleries[String(galleryId)]) {
      title = galleries[String(galleryId)];
    }
    return title ? String(title) : "";
  }

  /**
   * Module address (e.g. "0.0.0.1") from the props Divi passes to a module
   * component or to a settings field.
   */
  function getAddress(props) {
    if (!props) return "";
    var info = props.moduleInfo || props.module || {};
    return String(info.address || props.address || info._key || props._key || "");
  }

  /**
   * Divi 4 does not tell a settings field which module it edits. The settings
   * modal keeps a reference to the module component a few levels up the React
   * tree, so the field reads the address from there.
   */
  function findModuleAddressFromNode(node) {
    if (!node) return "";
    var key = Object.keys(node).filter(function (k) {
      return k.indexOf("__reactInternalInstance") === 0 || k.indexOf("__reactFiber") === 0;
    })[0];
    var fiber = key ? node[key] : null;
    var depth = 0;
    while (fiber && depth < 80) {
      var props = fiber.memoizedProps;
      var module = props && props.module;
      if (module && module.props && module.props.address && (!module.props.type || module.props.type === SLUG)) {
        return String(module.props.address);
      }
      fiber = fiber.return;
      depth += 1;
    }
    return "";
  }

  function widgetIdFromAddress(address) {
    return String(address || "").replace(/\./g, "-").replace(/[^a-zA-Z0-9_-]/g, "");
  }

  var SUPPRESS_CLASS = "reacg-divi-suppress-modal";
  var SUPPRESS_TIMEOUT = 3000;

  /**
   * Canvas interactions open the panel only: the native settings modal that
   * Divi opens on the way is hidden (CSS) and closed as soon as the field has
   * mounted and grabbed the change handler.
   */
  function suppressNativeModal(address) {
    var topWin = getTopWindow();
    topWin.__reacgDiviSuppress = String(address || "");
    topWin.document.body.classList.add(SUPPRESS_CLASS);
    window.clearTimeout(topWin.__reacgDiviSuppressTimer);
    topWin.__reacgDiviSuppressTimer = topWin.setTimeout(releaseNativeModal, SUPPRESS_TIMEOUT);
  }

  function releaseNativeModal() {
    var topWin = getTopWindow();
    topWin.__reacgDiviSuppress = "";
    topWin.document.body.classList.remove(SUPPRESS_CLASS);
  }

  function isNativeModalSuppressed(address) {
    var topWin = getTopWindow();
    return !!topWin.__reacgDiviSuppress && topWin.__reacgDiviSuppress === String(address || "");
  }

  /**
   * Open the module's settings modal by double clicking the module in the
   * canvas (the field inside the modal then opens the panel). Divi's modal is
   * suppressed so that only the panel shows.
   */
  function openModuleSettings(address) {
    var appWin = getAppWindow() || (isAppFrame() ? window : null);
    if (!appWin || !address) return false;
    suppressNativeModal(address);
    var module = appWin.document.querySelector('.et_pb_module[data-address="' + address + '"]');
    if (!module) return false;
    var rect = module.getBoundingClientRect();
    ["mouseover", "mousedown", "mouseup", "click", "dblclick"].forEach(function (type) {
      module.dispatchEvent(
        new appWin.MouseEvent(type, {
          bubbles: true,
          cancelable: true,
          clientX: rect.left + 5,
          clientY: rect.top + 5,
          view: appWin,
        })
      );
    });
    return true;
  }

  function closePanelFor(widgetId) {
    var panel = getPanel();
    if (panel && panel.isOpen && !panel.isEmbedded && panel.currentWidgetId === String(widgetId)) {
      panel.close();
    }
  }

  /**
   * Close Divi's module settings modal through its "Save Changes" button; the
   * module keeps the values applied so far.
   */
  function closeModuleSettingsModal() {
    var doc = getTopWindow().document;
    var button = doc.querySelector(".et-fb-modal__module-settings .et-fb-button--success");
    if (!button) return false;
    button.click();
    return true;
  }

  /* ---------------------------------------------------------------- */
  /* App frame: clicks on the canvas open the module settings            */
  /* ---------------------------------------------------------------- */

  if (isAppFrame()) {
    document.addEventListener(
      "click",
      function (e) {
        var target = e.target;
        if (!target || !target.closest) return;
        var hit = target.closest(".et_pb_module .reacg-gallery, .et_pb_module .reacg-builder-open-modal-btn");
        if (!hit) return;
        var module = hit.closest(".et_pb_module");
        if (!module) return;
        e.preventDefault();
        e.stopImmediatePropagation();
        openModuleSettings(module.getAttribute("data-address"));
      },
      true
    );
  }

  /* ---------------------------------------------------------------- */
  /* Builder components (top window React)                              */
  /* ---------------------------------------------------------------- */

  var React = window.React;
  if (!React) {
    return;
  }

  var h = React.createElement;

  function icon(className) {
    return h(
      "svg",
      { className: className, "aria-hidden": "true", viewBox: "0 0 20 20", focusable: "false" },
      h("path", { d: ICON_PATH })
    );
  }

  /**
   * Settings field: shows the selected gallery and opens the panel.
   */
  var mountedFields = {};
  // Widgets whose native modal was closed by us: the panel must stay open.
  var keepPanelFor = {};

  function GalleryPickerField(props) {
    React.Component.call(this, props);
    this.openPanel = this.openPanel.bind(this);
    this.setNode = this.setNode.bind(this);
    this.node = null;
    this.address = "";
  }
  GalleryPickerField.prototype = Object.create(React.Component.prototype);
  GalleryPickerField.prototype.constructor = GalleryPickerField;
  GalleryPickerField.slug = FIELD_SLUG;

  GalleryPickerField.prototype.setNode = function (node) {
    this.node = node;
  };

  GalleryPickerField.prototype.getWidgetId = function () {
    if (!this.address) {
      this.address = getAddress(this.props) || findModuleAddressFromNode(this.node);
    }
    return widgetIdFromAddress(this.address);
  };

  GalleryPickerField.prototype.openPanel = function (e) {
    if (e && e.preventDefault) e.preventDefault();
    var self = this;
    var panel = getPanel();
    if (!panel) {
      console.error("ReacgBuilderModal is not loaded in the Divi top window.");
      return;
    }
    panel.open({
      galleryId: effectiveGalleryId(this.props.value),
      widgetId: this.getWidgetId(),
      onSave: function (savedGalleryId) {
        if (typeof self.props._onChange === "function") {
          self.props._onChange(self.props.name, String(parseGalleryId(savedGalleryId)));
        }
      },
    });
  };

  /**
   * Whether the native modal is only a vehicle for the panel: a fresh insert
   * (no gallery yet) or a click on the gallery / placeholder in the canvas.
   */
  GalleryPickerField.prototype.shouldAutoClose = function () {
    this.getWidgetId();
    return !effectiveGalleryId(this.props.value) || isNativeModalSuppressed(this.address);
  };

  GalleryPickerField.prototype.componentDidMount = function () {
    var widgetId = this.getWidgetId();
    mountedFields[widgetId] = true;
    this.openPanel();

    if (this.shouldAutoClose()) {
      keepPanelFor[widgetId] = true;
      window.setTimeout(function () {
        if (!closeModuleSettingsModal()) {
          delete keepPanelFor[widgetId];
        }
        releaseNativeModal();
      }, 50);
    } else {
      releaseNativeModal();
    }
  };

  GalleryPickerField.prototype.componentWillUnmount = function () {
    var widgetId = this.getWidgetId();
    delete mountedFields[widgetId];
    if (keepPanelFor[widgetId]) {
      delete keepPanelFor[widgetId];
      return;
    }
    // Tab switches re-mount the field; only close when it stays unmounted.
    window.setTimeout(function () {
      if (!mountedFields[widgetId]) closePanelFor(widgetId);
    }, PANEL_CLOSE_DELAY);
  };

  GalleryPickerField.prototype.render = function () {
    var galleryId = effectiveGalleryId(this.props.value);
    var title = galleryId ? getGalleryTitle(galleryId) || "#" + galleryId : text("text_no_gallery_selected", "No gallery selected");

    return h(
      "div",
      { className: "reacg-divi-field" + (this.shouldAutoClose() ? " reacg-divi-field--autoclose" : ""), ref: this.setNode },
      h("div", { className: "reacg-divi-field__title" }, text("text_selected_gallery", "Selected gallery:") + " ", h("strong", null, title)),
      h(
        "button",
        { type: "button", className: "reacg-divi-field__open", onClick: this.openPanel },
        icon(null),
        text("text_select_or_create", "Select or Create Gallery")
      ),
      h("p", { className: "reacg-divi-field__desc", dangerouslySetInnerHTML: { __html: text("text_field_description", "") } })
    );
  };

  /**
   * Module: placeholder until a gallery is chosen, then the gallery root which
   * is mounted with the bundle loaded in the app frame.
   */
  function REACG_DiviModule(props) {
    React.Component.call(this, props);
    this.mountTimer = null;
    this.mountAttempts = 0;
    this.renderStamp = String(Date.now());
    this.handleClickCapture = this.handleClickCapture.bind(this);
  }
  REACG_DiviModule.prototype = Object.create(React.Component.prototype);
  REACG_DiviModule.prototype.constructor = REACG_DiviModule;
  REACG_DiviModule.slug = SLUG;

  REACG_DiviModule.prototype.getAddress = function () {
    return getAddress(this.props);
  };

  REACG_DiviModule.prototype.getRootId = function () {
    var widgetId = widgetIdFromAddress(this.getAddress());
    return "reacg-root" + (widgetId || parseGalleryId(this.props.post_id));
  };

  REACG_DiviModule.prototype.handleClickCapture = function (e) {
    e.preventDefault();
    e.stopPropagation();
    openModuleSettings(this.getAddress());
  };

  REACG_DiviModule.prototype.mountGallery = function () {
    var self = this;
    var galleryId = effectiveGalleryId(this.props.post_id);
    if (!galleryId) return;

    var rootId = this.getRootId();
    var appWin = getAppWindow();
    var doc = appWin ? appWin.document : document;
    var root = doc.getElementById(rootId);

    if (root && String(root.getAttribute("data-gallery-id")) === String(galleryId)) {
      if (root.childElementCount > 0) {
        this.mountAttempts = 0;
        return;
      }
      var win = root.ownerDocument.defaultView || appWin;
      if (win && typeof win.reacg_mount_gallery === "function") {
        win.reacg_mount_gallery(root);
        this.mountAttempts = 0;
        return;
      }
      var loadApp = root.ownerDocument.getElementById("reacg-loadApp");
      if (loadApp) {
        loadApp.setAttribute("data-id", rootId);
        loadApp.click();
        this.mountAttempts = 0;
        return;
      }
    }

    this.mountAttempts += 1;
    if (this.mountAttempts < 60) {
      window.clearTimeout(this.mountTimer);
      this.mountTimer = window.setTimeout(function () {
        self.mountGallery();
      }, this.mountAttempts < 10 ? 100 : 250);
    }
  };

  REACG_DiviModule.prototype.componentDidMount = function () {
    this.mountGallery();
  };

  REACG_DiviModule.prototype.componentDidUpdate = function (prevProps) {
    if (String(prevProps.post_id) !== String(this.props.post_id)) {
      this.renderStamp = String(Date.now());
      this.mountAttempts = 0;
    }
    this.mountGallery();
  };

  REACG_DiviModule.prototype.componentWillUnmount = function () {
    window.clearTimeout(this.mountTimer);
  };

  REACG_DiviModule.prototype.render = function () {
    var galleryId = effectiveGalleryId(this.props.post_id);
    var widgetId = widgetIdFromAddress(this.getAddress());

    if (!galleryId) {
      return h(
        "div",
        { className: "reacg-builder-placeholder", "data-widget-id": widgetId },
        h("div", { className: "reacg-builder-placeholder-icon" }, h("img", { src: text("plugin_url", "") + "/assets/images/icon.svg", alt: text("text_brand", "Re Gallery") })),
        h("div", { className: "reacg-builder-placeholder-title" }, text("text_brand", "Re Gallery")),
        h("p", { className: "reacg-builder-placeholder-desc" }, text("text_placeholder_desc", "No gallery selected yet. Select an existing gallery or create a new one.")),
        h(
          "button",
          { type: "button", className: "reacg-builder-open-modal-btn button button-primary", onClick: this.handleClickCapture },
          icon("reacg-builder-open-modal-btn__icon"),
          text("text_select_or_create", "Select or Create Gallery")
        )
      );
    }

    return h("div", {
      key: widgetId + ":" + galleryId,
      id: this.getRootId(),
      className: "reacg-wrapper reacg-gallery reacg-preview",
      "data-options-section": 0,
      "data-options-container": "#reacg_settings",
      "data-plugin-version": this.renderStamp,
      "data-gallery-timestamp": this.renderStamp,
      "data-options-timestamp": this.renderStamp,
      "data-widget-id": widgetId,
      "data-gallery-id": galleryId,
      onClickCapture: this.handleClickCapture,
    });
  };

  $(window).on("et_builder_api_ready", function (event, API) {
    API.registerModules([REACG_DiviModule]);
    API.registerModalFields([GalleryPickerField]);
  });
})(jQuery);
